"""Base classes for game library remote drivers."""

import abc
import math
from typing import Any, NewType

import numpy as np

from kaggle_evaluation.core import relay, telemetry
from kaggle_evaluation.core.base_gateway import GatewayRuntimeError, GatewayRuntimeErrorType, classify_server_error

# Separate type to prevent clashes with IDs generated by game libraries.
KaggleAgentId = NewType('KaggleAgentId', str)

# Agent id assumed when driver_config names none. Hosts building relay_clients need the same
# default the driver will apply, or the two disagree and the driver cannot find its own client.
DEFAULT_AGENT_ID = KaggleAgentId('agent_0')


def find_non_action(action: Any, path: str = 'action') -> str | None:
    """Locate the first null or non-finite number in an action, described as `<path> is None/nan/inf`.

    Returns None if the action is clean.

    An agent that fails to pick a move usually returns a non-action rather than raising: a JSON
    null, or the NaN or infinity a failed parse or a diverged model produces. None of those is a
    move in any game, and passing one on either crashes the environment - after the driver's error
    classification, so the gateway would report the submission's fault as Kaggle's - or silently
    poisons the game state. An unbounded Box contains an infinity set-theoretically, but no
    environment can act on one. Containers are searched recursively so a null buried in a Dict or
    Tuple action counts.
    """
    if action is None:
        return f'{path} is None'
    if isinstance(action, (float, np.floating)) and not math.isfinite(action):
        return f'{path} is {action}'
    if isinstance(action, np.ndarray):
        if action.dtype.kind in 'fc':
            return None if np.isfinite(action).all() else f'{path} contains a NaN or infinite value'
        if action.dtype.kind != 'O':
            return None
        # Object arrays can hold anything, including the nulls a numeric dtype cannot represent.
        children = ((f'{path}[{index}]', value) for index, value in np.ndenumerate(action))
    elif isinstance(action, dict):
        children = ((f'{path}[{key!r}]', value) for key, value in action.items())
    elif isinstance(action, (list, tuple)):
        children = ((f'{path}[{index}]', value) for index, value in enumerate(action))
    else:
        return None

    for child_path, value in children:
        found = find_non_action(value, child_path)
        if found:
            return found
    return None


class BaseSerializer[GameData](abc.ABC):
    @abc.abstractmethod
    def serialize(self, data: Any) -> Any:
        """Serialize game data to a format suitable for networking.

        Must handle all game-specific types including:
        - Action spaces (e.g., gym.Space objects)
        - Observation values
        - Additional game data (e.g., info dicts)

        Types natively supported by the networking host (primitives, Pydantic models, enums, dataclasses)
        should be returned as-is without serialization. Only custom types need JSON string serialization.

        Returns:
            Either the original data (if natively supported) or a JSON string (if custom serialization needed).
        """
        raise NotImplementedError

    @abc.abstractmethod
    def deserialize(self, data: Any) -> Any:
        """Deserialize data from the networking format.

        Must handle all game-specific types including:
        - Action spaces (e.g., gym.Space objects)
        - Observation values
        - Additional game data (e.g., info dicts)

        Args:
            data: Either native types (Pydantic models, enums, dataclasses, primitives) or JSON strings.

        Returns:
            The deserialized game data.
        """
        raise NotImplementedError


class BaseRemoteAgent[GameData, Action, ActionSpace, Observation](abc.ABC):
    """Base class for remote agents that interact with game environments.

    Subclasses must implement:
    - process_turn: Relay endpoint that handles serialization between relay and choose_action.
    - choose_action: Game-specific logic for selecting actions.
    """

    @abc.abstractmethod
    def process_turn(self, *args, **kwargs) -> dict[str, Any]:
        """Entry point called by the relay server. Sits between relay and choose_action.

        This method handles any serialization that relay cannot perform natively, such as
        converting Pydantic models to library-specific types (e.g., gymnasium.spaces.Space).
        The exact signature varies by game library, but the return value must be a dict
        containing at minimum an 'action' key.

        Game libraries that only require types supported by relay (primitives, enums, dataclasses,
        Pydantic models) can implement process_turn as a simple pass-through to choose_action.

        Returns:
            Dictionary with 'action' and optionally 'reasoning' keys.
        """
        raise NotImplementedError

    @abc.abstractmethod
    def choose_action(
        self, action_space: ActionSpace, observation: Observation, info: dict[str, Any] | None = None
    ) -> Action | tuple[Action, str | None]:
        """Core method to be implemented by the end user. Choose an action given the current game state.

        Args:
            action_space: Deserialized action space (native library type, e.g., gymnasium.spaces.Space)
            observation: Deserialized observation
            info: Optional additional game-specific data (e.g., action masks for OpenSpiel)

        Returns:
            Either:
            - action: The chosen action
            - (action, reasoning): Action with optional reasoning string for logging
        """
        raise NotImplementedError


# Standard endpoint name for agent turn processing. All game drivers use this endpoint.
PROCESS_TURN_ENDPOINT: str = BaseRemoteAgent.process_turn.__name__


class BaseGameDriver[GameData, Action](abc.ABC):
    def __init__(
        self,
        driver_config: dict[str, Any] | None = None,
        relay_clients: dict[KaggleAgentId, relay.Client] | None = None,
    ) -> None:
        """
        Args:
            driver_config: dict. Used for game-specific configuration such as setting which agent goes first.
                Intended to mirror the args accepted by kaggle-environments main.py that are related to agents:
                https://github.com/Kaggle/kaggle-environments/blob/master/kaggle_environments/main.py#L25
                Accepts command line arguments, so relay_clients is passed separately.
            relay_clients: Dict mapping agent IDs to their relay clients. Each agent runs in a separate
                container with its own relay connection.

        driver_config fields:
            agent_ids: Agent(s) to run with the environment. Maps to KE arg agents
            agent_config: Information about agents playing. Maps to KE arg info.
            game_config: Configuration to setup the game. Maps to KE arg configuration.
        """
        self.driver_config = driver_config
        if driver_config is None:
            self.agent_ids: list[KaggleAgentId] = [DEFAULT_AGENT_ID]
            self.agent_config: dict[KaggleAgentId, dict[str, Any]] = {}
            self.game_config: dict[str, Any] = {}
        else:
            self.agent_ids: list[KaggleAgentId] = [KaggleAgentId(agent_id) for agent_id in driver_config.get('agent_ids', [DEFAULT_AGENT_ID])]
            self.agent_config: dict[KaggleAgentId, dict[str, Any]] = {
                KaggleAgentId(agent_id): info for agent_id, info in driver_config.get('agent_config', {}).items()
            }
            self.game_config: dict[str, Any] = driver_config.get('game_config', {})

        self.relay_clients: dict[KaggleAgentId, relay.Client] = relay_clients or {}
        if self.relay_clients and len(self.relay_clients) != len(self.agent_ids):
            raise ValueError(f'Number of relay_clients ({len(self.relay_clients)}) must match number of agent_ids ({len(self.agent_ids)})')

        # The count check above passes for the right number of clients under the wrong keys, which is
        # what a config naming its own agent ids produces. Left to run, that surfaces mid-game as a
        # missing client, which the gateway reports as a Kaggle-side fault rather than the host's
        # misconfiguration. Cheaper to refuse the pairing before the game starts.
        missing_clients = [agent_id for agent_id in self.agent_ids if agent_id not in self.relay_clients]
        if self.relay_clients and missing_clients:
            raise ValueError(f'No relay_clients entry for agent_ids {missing_clients}. Got keys {list(self.relay_clients)}')

    def __init_subclass__(cls, **kwargs):
        # Instrument every driver subclass with telemetry spans, mirroring BaseGateway. Spans are
        # opt-in (TelemetryLevel.NONE by default), so this is free unless a deployer enables tracing.
        super().__init_subclass__(**kwargs)
        telemetry.wrap_with_span(cls)

    def _align_agent_ids(self, env_agent_ids: list[str | int]):
        """Ensure self.agent_ids has the same length as the environment's agent ids.
        Pad with new agent names if self.agent_ids is using the default name.
        """
        num_env_agents = len(env_agent_ids)
        is_default_agent_id = self.agent_ids == [DEFAULT_AGENT_ID]

        if is_default_agent_id and num_env_agents > 1:
            self.agent_ids = [KaggleAgentId(f'agent_{i}') for i in range(num_env_agents)]
        elif len(self.agent_ids) != num_env_agents:
            raise ValueError(
                f'The number of agents specified in driver_config ({len(self.agent_ids)}) '
                f'does not match the number of agents in the environment ({num_env_agents}).'
            )

    @abc.abstractmethod
    def start_new_game(
        self,
        game_name: str,
        random_seed: int | None = None,
        game_state: str | None = None,
        action_timeout: int | None = 60,
    ) -> None:
        """Set up but do not run the game. Returns the information needed for the first turn.
        Needs to account for the possibility that another game has already been run and reset all assets.
        This is similar to a gymnasium reset.

        Args:
            game_name: The name of the game to start.
            random_seed: Seed for the random number generator to ensure reproducibility.
            game_state: Optional initial state to start the game from. Must accept strings so we can pass game state via the command line.
            action_timeout: Time limit in seconds for agents to take an action.

        Returns:
            None. This differs from Gym/PettingZoo's env.reset definitions, which have a variety of return types.
            For our purposes it's simplest to always return none and add a separate call to get the initial game state if needed.
        """
        raise NotImplementedError

    def get_agent_action(self, game_data: GameData, agent_id: KaggleAgentId, info: dict[str, Any] | None = None) -> tuple[Action, str | None]:
        """Get an action from an agent, reporting any failure as a GatewayRuntimeError.

        Drivers talk to the inference server directly rather than through the gateway's own
        `predict`/`send_to_server`, so this is the only thing standing between a failed turn and
        the gateway's catch-all, which reports whatever it cannot classify as a Kaggle-side fault.

        Subclasses implement the exchange itself in `_get_agent_action`; wrapping it here rather
        than in each driver keeps a competition gateway from having to redo the classification.
        Nulls, NaNs and infinities are rejected here for the same reason: see `find_non_action`. A
        game where one of those is a legal move has to override this method.

        Args:
            game_data: The current game state or relevant information for the agent.
            agent_id: The ID of the agent to get the action from.
            info: Optional additional game-specific data (e.g., action masks for OpenSpiel).

        Returns:
            action: The agent's action in whatever format is used by the game engine.
            reasoning: The LLM's reasoning context, if any. For logging purposes only.
        """
        try:
            action, reasoning = self._get_agent_action(game_data, agent_id, info)
        except GatewayRuntimeError:
            # Already attributed by the driver. Falling through would hand it to
            # classify_server_error, which matches on the message - agent-supplied text here.
            raise
        except Exception as exception:  # noqa: BLE001 -- classify_server_error handles every failure and always re-raises.
            classify_server_error(exception, PROCESS_TURN_ENDPOINT)

        non_action = find_non_action(action)
        if non_action:
            raise GatewayRuntimeError(GatewayRuntimeErrorType.INVALID_SUBMISSION, f'agent {agent_id}: {non_action}')
        return action, reasoning

    @abc.abstractmethod
    def _get_agent_action(self, game_data: GameData, agent_id: KaggleAgentId, info: dict[str, Any] | None) -> tuple[Action, str | None]:
        """Send json-serialized data to a specific agent and optionally get a response.

        For a typical game like chess this might include the board state and a list of legal moves.

        Raises:
            GatewayRuntimeError: The driver can tell the failure is the submission's fault, such as
                a response it cannot read as an action. `get_agent_action` classifies anything else,
                so a relay failure should propagate untouched rather than be labelled here.
        """
        raise NotImplementedError

    @abc.abstractmethod
    def step(self, action: Action | dict[str, Action]) -> GameData | None:
        """Advance the game state."""
        raise NotImplementedError

    @abc.abstractmethod
    def get_still_playing(self) -> dict[KaggleAgentId, bool]:
        """Maps agent_id to whether they are still active in the game. All will be false if the game is over.
        May need to be revised later to support more complicated states, such as multiple rounds of poker where an agent may be only temporarily inactive.
        """
        raise NotImplementedError

    @property
    def episode_complete(self) -> bool:
        """Whether the game has ended, i.e. no agent is still playing.

        Derived from get_still_playing() so each driver defines game-over in exactly one place.
        """
        return not any(self.get_still_playing().values())

    @abc.abstractmethod
    def get_results(self) -> dict[KaggleAgentId, float | int]:
        """Returns {scores:{agent_id: {score: float | int} | {error: str}}."""
        # TODO: Refactor to record errors as well.
        raise NotImplementedError

    @abc.abstractmethod
    def run_game(self, game_name: str) -> dict[KaggleAgentId, float | int]:
        """Run a full game with the given agents."""
        raise NotImplementedError

    def get_full_state(self) -> dict[str, Any]:
        """For visualizing and debugging imperfect information games."""
        raise NotImplementedError

    def render(self, game_state: str, mode: str):
        """Visualize the current game state."""
        raise NotImplementedError


# Wrap the base class's own concrete methods; __init_subclass__ handles every subclass.
telemetry.wrap_with_span(BaseGameDriver)
